import { forwardRef, useId, type HTMLAttributes, type ReactNode } from "react";

import { cn } from "@/lib/cn";
import { Progress, type ProgressTone } from "./progress.js";

/** Props accepted by QuotaMeter. */
export type QuotaMeterProps = {
  label: ReactNode;
  value: number;
  max: number;
  valueLabel?: ReactNode;
  maxLabel?: ReactNode;
  description?: ReactNode;
  indicator?: ReactNode;
  tone?: ProgressTone;
} & Omit<HTMLAttributes<HTMLDivElement>, "children">;

/** A meter presentation for caller-provided quota values. */
export const QuotaMeter = forwardRef<HTMLDivElement, QuotaMeterProps>(
  function QuotaMeter(
    {
      className,
      label,
      value,
      max,
      valueLabel,
      maxLabel,
      description,
      indicator,
      tone,
      ...props
    },
    ref,
  ) {
    const id = useId();
    const labelId = `${id}-label`;
    const descriptionId = `${id}-description`;

    return (
      <div {...props} className={cn("space-y-sm", className)} ref={ref}>
        <div className="flex items-center justify-between gap-sm">
          <div className="flex items-center gap-sm">
            <div className="font-medium" id={labelId}>
              {label}
            </div>
            {indicator !== undefined ? <div>{indicator}</div> : null}
          </div>
          <div className="caps-numeric">
            {valueLabel ?? value} / {maxLabel ?? max}
          </div>
        </div>
        <Progress
          aria-describedby={
            description !== undefined ? descriptionId : undefined
          }
          aria-labelledby={labelId}
          max={max}
          {...(tone === undefined ? {} : { tone })}
          value={value}
        />
        {description !== undefined ? (
          <p className="text-sm text-base-content" id={descriptionId}>
            {description}
          </p>
        ) : null}
      </div>
    );
  },
);

import {
  forwardRef,
  type HTMLAttributes,
  type ProgressHTMLAttributes,
} from "react";

import { cn } from "@/lib/cn";

/** Supported ProgressTone values. */
export type ProgressTone =
  | "neutral"
  | "primary"
  | "secondary"
  | "accent"
  | "success"
  | "info"
  | "warning"
  | "error";

const progressToneClasses = {
  neutral: "progress-neutral",
  primary: "progress-primary",
  secondary: "progress-secondary",
  accent: "progress-accent",
  success: "progress-success",
  info: "progress-info",
  warning: "progress-warning",
  error: "progress-error",
} satisfies Record<ProgressTone, string>;

/** Props accepted by Progress. */
export type ProgressProps = {
  tone?: ProgressTone;
} & ProgressHTMLAttributes<HTMLProgressElement>;

/** A progress indicator for caller-provided progress values. */
export const Progress = forwardRef<HTMLProgressElement, ProgressProps>(
  function Progress({ className, tone = "primary", ...props }, ref) {
    return (
      <progress
        {...props}
        data-complete={
          props.value !== undefined &&
          Number(props.value) >= Number(props.max ?? 1)
            ? "true"
            : undefined
        }
        className={cn(
          "progress caps-gooey-motion caps-gooey-progress w-full",
          progressToneClasses[tone],
          className,
        )}
        ref={ref}
      />
    );
  },
);

/** A compact labelled resource meter for game windows. Values come from the game. */
export type GameMeterProps = Omit<
  HTMLAttributes<HTMLDivElement>,
  "children"
> & {
  label: string;
  value: number;
  max: number;
  tone?: ProgressTone;
};

/** Pair a game's bounded resource value with its visible and accessible meter. */
export const GameMeter = forwardRef<HTMLDivElement, GameMeterProps>(
  function GameMeter(
    { label, value, max, tone = "info", className, ...props },
    ref,
  ) {
    return (
      <div {...props} ref={ref} className={cn("caps-game-meter", className)}>
        <div className="caps-game-meter-readout">
          <span>{label}</span>
          <span className="caps-game-meter-value">
            {value} / {max}
          </span>
        </div>
        <Progress aria-label={label} value={value} max={max} tone={tone} />
      </div>
    );
  },
);

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}
